/** نرمال‌سازی نام فارسی برای تطبیق تکراری‌ها */
function norm(s) {
  return String(s || "")
    .replace(/[\u200c\u200f\u200e]/g, "")
    .replace(/[يى]/g, "ی")
    .replace(/ك/g, "ک")
    .replace(/[أإآ]/g, "ا")
    .replace(/ة/g, "ه")
    .replace(/ؤ/g, "و")
    .replace(/\s+/g, " ")
    .trim()
    .toLowerCase();
}

function loadEnv() {
  if (process.env.DATABASE_URL) return;
  for (const f of [".env", ".env.local"]) {
    try {
      const txt = fs.readFileSync(path.resolve(process.cwd(), f), "utf8");
      const m = txt.match(/^\s*DATABASE_URL\s*=\s*"?([^"\r\n]+)"?\s*$/m);
      if (m && m[1].trim()) {
        process.env.DATABASE_URL = m[1].trim();
        break;
      }
    } catch {
      /* فایل نبود */
    }
  }
}

function resolveDbPath() {
  const url = process.env.DATABASE_URL || "";
  const p = url.replace(/^file:/, "").trim();
  if (!p) return null;
  if (path.isAbsolute(p)) return fs.existsSync(p) ? p : null;
  for (const rel of [
    path.resolve(process.cwd(), p),
    path.resolve(process.cwd(), "prisma", p),
    path.resolve(process.cwd(), "db", p),
  ]) {
    if (fs.existsSync(rel)) return rel;
  }
  return null;
}

async function makeBackup(db) {
  const stamp = new Date().toISOString().replace(/[:.]/g, "-").slice(0, 19);
  const backupDir = path.join(process.cwd(), "db", "backups");
  const out = path.join(backupDir, `pre-food-sync-${stamp}-${Math.random().toString(36).slice(2, 6)}.db`);
  try {
    fs.mkdirSync(backupDir, { recursive: true });
    fs.rmSync(out, { force: true });
    await db.$executeRawUnsafe(`VACUUM INTO '${out.replace(/'/g, "''")}'`);
    return out;
  } catch {
    /* روش دوم: checkpoint + کپی فایل */
  }
  try {
    const dbPath = resolveDbPath();
    if (!dbPath) return null;
    try {
      await db.$queryRawUnsafe("PRAGMA wal_checkpoint(TRUNCATE)");
    } catch {
      /* checkpoint اختیاری */
    }
    fs.mkdirSync(backupDir, { recursive: true });
    fs.copyFileSync(dbPath, out);
    for (const ext of ["-wal", "-shm"]) {
      if (fs.existsSync(dbPath + ext)) fs.copyFileSync(dbPath + ext, out + ext);
    }
    return out;
  } catch {
    return null;
  }
}

const fa = (n) => Number(n ?? 0).toLocaleString("fa-IR");

async function main() {
  console.log("════════════════════════════════════════════════════════════");
  console.log("  فیتاپ — افزودن ۵۰۰ غذای جدید به بانک کالری پروداکشن");
  if (DRY) console.log("  (حالت DRY-RUN — هیچ تغییری نوشته نمی‌شود)");
  console.log("════════════════════════════════════════════════════════════");

  loadEnv();
  if (!process.env.DATABASE_URL) {
    console.error("❌ DATABASE_URL پیدا نشد. اسکریپت را در پوشهٔ اصلی پروژه (کنار package.json و .env) اجرا کنید.");
    process.exit(1);
  }
  let PrismaClient;
  try {
    ({ PrismaClient } = require("@prisma/client"));
  } catch {
    console.error("❌ @prisma/client در node_modules پیدا نشد. اسکریپت را در پوشهٔ اصلی پروژه بگذارید.");
    process.exit(1);
  }
  const db = new PrismaClient();

  try {
    const totalBefore = await db.foodLibrary.count();
    console.log(`\n📂 دیتابیس: ${process.env.DATABASE_URL.replace(/^file:/, "")}`);
    console.log(`🔢 تعداد غذاهای فعلی: ${fa(totalBefore)}`);

    if (!DRY) {
      console.log("\n💾 در حال تهیهٔ بکاپ کامل…");
      const backupPath = await makeBackup(db);
      if (!backupPath) {
        if (process.env.SYNC_FORCE === "1") {
          console.warn("⚠️  بکاپ انجام نشد — چون SYNC_FORCE=1 است ادامه می‌دهیم (ریسک با شماست).");
        } else {
          console.error("❌ بکاپ خودکار انجام نشد (دسترسی نوشتن در db/backups را چک کنید).");
          console.error("   برای اطمینان هیچ تغییری اعمال نشد. بعد از رفع دسترسی دوباره اجرا کنید.");
          console.error("   (عبور اجباری بدون بکاپ: SYNC_FORCE=1 node prod-sync-foods-v137.mjs)");
          process.exit(1);
        }
      } else {
        console.log(`✅ بکاپ کامل: ${backupPath}`);
      }
    }

    // نقشهٔ نام‌های موجود — ضد تکرار (نرمال‌سازی فارسی)
    const existing = await db.foodLibrary.findMany({ select: { name: true } });
    const namesByNorm = new Set(existing.map((r) => norm(r.name)));

    let added = 0;
    let skippedDup = 0;
    const addedNames = [];
    let i = 0;
    for (const f of FOODS) {
      i++;
      const n = norm(f.name);
      if (namesByNorm.has(n)) {
        skippedDup++;
        continue;
      }
      if (!DRY) {
        await db.foodLibrary.create({
          data: {
            id: f.id,
            name: f.name,
            category: f.category,
            calories: f.calories,
            protein: f.protein,
            carbs: f.carbs,
            fat: f.fat,
            servingSize: f.servingSize,
            isVegan: !!f.isVegan,
            imageUrl: "",
          },
        });
      }
      namesByNorm.add(n);
      added++;
      if (addedNames.length < 15) addedNames.push(f.name);
      if (i % 100 === 0) console.log(`   … ${fa(i)} / ${fa(FOODS.length)}`);
    }

    const totalAfter = DRY ? totalBefore + added : await db.foodLibrary.count();
    console.log("\n────────────────────────────── گزارش ──────────────────────────────");
    console.log(`   غذای جدید اضافه‌شده : ${fa(added)}`);
    console.log(`   رد‌شده (تکراری با بانک شما) : ${fa(skippedDup)}`);
    console.log(`   جمع بانک غذا بعد از سینک : ${fa(totalAfter)} (قبل: ${fa(totalBefore)})`);
    if (addedNames.length) {
      console.log("\n➕ نمونهٔ غذاهای اضافه‌شده:");
      for (const n of addedNames) console.log(`   • ${n}`);
    }
    console.log("───────────────────────────────────────────────────────────────────");
    console.log("\n✅ تمام شد. هیچ تغییری در غذاهای قبلی شما داده نشد.");
    console.log("ℹ️  اجرای دوباره بی‌ضرر است (idempotent).");
  } finally {
    await db.$disconnect().catch(() => {});
  }
}

main().catch((e) => {
  console.error("\n❌ خطا در اجرای سینک غذاها:", e?.message ?? e);
  process.exit(1);
});
